const fs = require('fs');

function main() {
    const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
    const n = parseInt(data[0], 10);

    const full = new Set();
    const pref = Array.from({ length: 11 }, () => new Set());
    const suff = Array.from({ length: 11 }, () => new Set());

    for (let i = 0; i < n; i++) {
        const s = data[i + 1];
        let bad = false;

        if (full.has(s)) {
            bad = true;
        } else {
            for (let len = 1; len <= 9; len++) {
                const left = s.slice(0, len);
                const right = s.slice(len);

                if (suff[len].has(left) && pref[10 - len].has(right)) {
                    bad = true;
                    break;
                }
            }
        }

        if (bad) {
            process.stdout.write(s + '\n');
            return;
        }

        full.add(s);

        for (let len = 1; len <= 9; len++) {
            pref[len].add(s.slice(0, len));
            suff[len].add(s.slice(10 - len));
        }
    }

    process.stdout.write('ok\n');
}

main();
